package main

import (
    "net/http"
    "net/http/httptest"
    "testing"
    "time"
    "github.com/labstack/echo/v4"
)

func TestIconCacheExpiryUsesReadStart(t *testing.T) {
    clearIconHashCache()
    cache:=activeIconHashes.Load()
    started:=time.Now().Add(-iconHashCacheTTL/2)
    cache.put("alice",`"hash"`,started)
    if !cache.matches("alice",`"hash"`,started.Add(iconHashCacheTTL/2)) { t.Fatal("fresh cached ETag did not match") }
    if cache.matches("alice",`"hash"`,started.Add(iconHashCacheTTL)) { t.Fatal("cached ETag exceeded freshness deadline") }
    if cache.matches("alice","",started.Add(iconHashCacheTTL/2)) { t.Fatal("unconditional GET must not use cached 304") }
    if cache.matches("alice",`"different"`,started.Add(iconHashCacheTTL/2)) { t.Fatal("different ETag matched") }
}
func TestIconCacheResetIsolatesInFlightReads(t *testing.T) {
    clearIconHashCache()
    oldCache:=activeIconHashes.Load()
    clearIconHashCache()
    oldCache.put("alice",`"old-generation"`,time.Now())
    if activeIconHashes.Load().matches("alice",`"old-generation"`,time.Now()) { t.Fatal("pre-initialization read populated new cache") }
